css:
.toggle-wrapper {
  display: flex;
  justify-content: center;
  align-items: center;
  position: relative;
  border-radius: 0.2em;
  padding: 0.15em;
  background: linear-gradient(to right, #1a1a1a, #2c2c2c);
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.5);
  font-size: 1.5em; /* Keep demo size */
}

.toggle-checkbox {
  appearance: none;
  position: absolute;
  z-index: 1;
  border-radius: inherit;
  width: 100%;
  height: 100%;
  font: inherit;
  opacity: 0;
  cursor: pointer;
}

.toggle-container {
  display: flex;
  align-items: center;
  position: relative;
  border-radius: 0.1em;
  width: 4em;
  height: 1.6em;
  background-color: #222222;
  box-shadow: inset 0 0 0.1em rgba(0, 0, 0, 0.8);
  overflow: hidden;
  transition: background-color 0.3s ease;
}

.toggle-background {
  position: absolute;
  width: 50%;
  height: 100%;
  left: 0;
  background: linear-gradient(to right, #ff0066, #ff4d94);
  transition:
    left 0.3s ease,
    transform 0.3s ease;
}

.toggle-checkbox:checked + .toggle-container > .toggle-background {
  left: 50%;
  transform: scaleX(1.1);
}

.toggle-button {
  display: flex;
  justify-content: center;
  align-items: center;
  position: absolute;
  left: 0.2em;
  border-radius: 0.1em;
  width: 1.8em;
  height: 1.2em;
  background: linear-gradient(to bottom, #ffffff, #d9d9d9);
  box-shadow: 0 0 0.2em rgba(255, 255, 255, 0.3);
  transition: left 0.3s ease;
}

.toggle-checkbox:checked + .toggle-container > .toggle-button {
  left: 2em;
}

.toggle-checkbox:checked + .toggle-container {
  background-color: #1a1a1a;
}
